// Unicamente declara los parametros de ESTA corrida manual DEV (fechas, candidatos ya "listados" en Drive -simulados-, rutas locales de fixtures, usuario). NINGUNA regla de negocio: son solo los inputs que un futuro paso real de Drive/UI proveeria.
// Rutas bajo ~/.n8n-files/ (unico directorio DEV permitido por N8N_RESTRICT_FILE_ACCESS_TO ademas del POC real de V2, que nunca se toca desde V3).
return [{
  json: {
    fecha_inicio: '2026-09-01',
    fecha_fin: '2026-09-01',
    drive_folder_entrada: 'DEV-sin-conectar',
    candidatos_por_fecha: {
      '2026-09-01': ['CIERRE 01-09-2026.xlsm'],
    },
    base_dir_dev: '/home/codespace/.n8n-files/tiq_v3_manual_dev/dev_workdir',
    origen_cierres_dir: '/home/codespace/.n8n-files/tiq_v3_manual_dev/origen_drive',
    ruta_maestro_origen: '/home/codespace/.n8n-files/tiq_v3_manual_dev/MAESTRO_SEPTIEMBRE.xlsm',
    ruta_plantilla_origen: '/home/codespace/.n8n-files/tiq_v3_manual_dev/Plantilla_SAP_maestra.xlsx',
    markers_origen_dir: null,
    mes_rango: 9,
    version_codigo: 'v3-dev-manual',
    usuario_auditor: 'auditor.dev',
    controles_dir_dev: null,
    correcciones_por_fecha: {},
  },
}];

// Estructural: el Modulo 01 (INGESTA) devuelve UN item n8n por fecha (patron nativo de n8n); el Modulo 02 (MATERIALIZACION) espera UN solo array 'cierres_ingesta' con todas las fechas juntas. Este nodo solo agrupa items en un array -- no decide ni calcula nada.
const cierres = $input.all().map((item) => item.json);
return [{ json: { cierres_ingesta: cierres } }];

// Estructural: separa los cierres YA clasificados por el Modulo 04 segun el campo estado_final que ESE modulo ya decidio -- este nodo no aplica ningun criterio nuevo, solo particiona el mismo array en 3 listas para que el workflow sepa a que subworkflow enviar cada uno despues.
// NOTA: el nodo INTERPRETAR (extractFromFile) del subworkflow envuelve su salida bajo $json.data.*
const cierres = ($json.data && $json.data.cierres) || [];
const listos = cierres.filter((c) => c.estado_final === 'LISTO_PARA_PUBLICAR');
const porRevisar = cierres.filter((c) => c.estado_final === 'ERROR_REVISAR');
const otros = cierres.filter((c) => c.estado_final !== 'LISTO_PARA_PUBLICAR' && c.estado_final !== 'ERROR_REVISAR');
return [{ json: { listos, por_revisar: porRevisar, otros } }];

// Estructural + DEV: adjunta, a cada cierre ERROR_REVISAR, la correccion YA AUTORIZADA por el auditor humano (aqui, un fixture de la corrida DEV manual) -- si no hay correccion para esa fecha, el cierre sigue sin "correccion" y el Modulo 05 lo dejara pendiente (nunca inventa una correccion).
const correccionesPorFecha = $('SET - Datos DEV (manual)').item.json.correcciones_por_fecha || {};
const porRevisar = $json.por_revisar || [];
const conCorreccion = porRevisar.map((c) => ({ ...c, correccion: correccionesPorFecha[c.fecha] || null }));
return [{ json: { cierres_con_correccion: conCorreccion } }];

// Estructural: separa los reprocesos del Modulo 05 segun resultado_reproceso -- campo que ESE modulo ya decidio.
// NOTA: el nodo INTERPRETAR (extractFromFile) del subworkflow envuelve su salida bajo $json.data.*
const cierres = ($json.data && $json.data.cierres) || [];
const listos = cierres.filter((c) => c.resultado_reproceso === 'LISTO_PARA_PUBLICAR');
const pendientes = cierres.filter((c) => c.resultado_reproceso !== 'LISTO_PARA_PUBLICAR');
return [{ json: { reprocesos_listos: listos, reprocesos_pendientes: pendientes } }];

// Estructural: junta, en UNA sola lista, los cierres que quedaron publicables -- los que el Modulo 04 ya marco LISTO_PARA_PUBLICAR directamente, y los que el Modulo 05 dejo LISTO_PARA_PUBLICAR tras un reproceso autorizado. Ninguna decision nueva: solo union de 2 listas ya decididas.
const listosDirectos = $('RUTEAR - Por estado_final (04)').item.json.listos || [];
const listosReprocesados = $json.reprocesos_listos || [];
return [{ json: { cierres_listos: [...listosDirectos, ...listosReprocesados] } }];

// Estructural: construye el conjunto COMPLETO de cierres finales para auditoria (publicados o no) -- nunca cambia ningun estado ya decidido, solo une por fecha el resultado de publicacion (si lo hubo) sobre el item correspondiente.
// NOTA: el nodo INTERPRETAR (extractFromFile) del subworkflow envuelve su salida bajo $json.data.*
const publicados = ($json.data && $json.data.cierres) || [];
const otros04 = $('RUTEAR - Por estado_final (04)').item.json.otros || [];
const pendientes05 = $('RUTEAR - Reprocesos (05)').item.json.reprocesos_pendientes || [];
const listosDirectos04 = $('RUTEAR - Por estado_final (04)').item.json.listos || [];
const listosReprocesados05 = $('RUTEAR - Reprocesos (05)').item.json.reprocesos_listos || [];
const porFecha = {};
for (const c of [...otros04, ...pendientes05, ...listosDirectos04, ...listosReprocesados05]) { porFecha[c.fecha] = c; }
for (const p of publicados) { porFecha[p.fecha] = p; }
return [{ json: { cierres_finales: Object.values(porFecha) } }];
